parameters.jsCode:
const input = $input.first().json;
const opportunityId = Number(input.opportunity_id);
const captureEventId = Number(input.capture_event_id);
const tier = String(input.routing_tier || 'owner');
if (!Number.isSafeInteger(opportunityId) || opportunityId <= 0) throw new Error('valid opportunity_id required');
if (!Number.isSafeInteger(captureEventId) || captureEventId <= 0) throw new Error('valid capture_event_id required');
if (!['owner', 'primary_guard'].includes(tier)) throw new Error('invalid routing tier');
const easybrokerUrl = String(input.easybroker_url || '').trim();
if (!/^https:\/\/(?:www\.)?easybroker\.com\//i.test(easybrokerUrl)) throw new Error('easybroker_public_url_required');
const number = input.owner_number || input.recipient_number || null;
const button_id = 'claim:v3';
const text = ['Nuevo prospecto para ' + (input.property_title || 'una propiedad'), 'Lead: ' + (input.lead_name || 'Sin nombre'), 'Tienes 5 minutos desde la entrega confirmada.'].join('\\n');
return [{ json: { ...input, easybroker_url: easybrokerUrl, opportunity_id: opportunityId, capture_event_id: captureEventId, routing_tier: tier, button_id, text, number, target_agent_id: input.owner_agent_id || input.agent_id || input.target_agent_id || null } }];

